::v-deep .el-dialog{
  background-color: #f5f6fa;
}
::v-deep .el-dialog__title{
  font-size: 16px;
}
.wrapper{
  display: flex;
  padding: 16px 96px;
  align-items: center;
  justify-content: space-between;
}
.radius-md {
  border-radius: 8px;
}
.bg-block {
  background-color: #fff;
}
.wrapper .item-left {
  width: 70px;
  text-align: center;
  z-index: 2;
}
.text-primary {
  color: #1670f0;
}
.wrapper .reledit-icon {
  width: 70px;
  height: 70px;
  border: 1px solid;
  font-size: 35px;
  text-align: center;
  padding-top: 0px;
  border-width: 1px;
  border-radius: 2px;
  border-style: solid;
  display: flex;
  justify-content: center;
  align-items: center;
  margin-bottom: 4px;
  margin-top: 4px;
}
.wrapper .reledit-switch {
  cursor: pointer;
  width: 32px;
  height: 32px;
  border-radius: 32px;
  border: 1px solid;
  z-index: 2;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 20px;
}
.wrapper .reledit-line {
  top: 88px;
  left: 190px;
  right: 190px;
  height: 1px;
  border-top: 1px solid;
  z-index: 0;
  position: absolute;
}

.wrapper .item-right {
  width: 70px;
  z-index: 2;
  text-align: center;
}



.text-grey{
  color: #8c8c8c;
  fill: #8c8c8c;
}
.border-primary {
  border-color: #1670f0;
}
.overflow {
  overflow: hidden;
  text-overflow: ellipsis;
  word-break: break-all;
  white-space: nowrap;
}
.border-color {
  border-color: var(--border-color, #e5e5e5) !important;
}

.moshi1{
  display: flex;
  justify-content: space-between
}
.moshi2{
  display: flex;
  justify-content: space-between;
  font-size: 12px;

  .moshi2-l{
    width: 50%;
    margin-right: 15px
  }
  .moshi2-r{
    width: 50%;
  }
}
.moshi3-r{
  display: flex;
  justify-content: flex-end;
  align-items: center;
  .moshi3-rl{
    margin-right: 5px;
  }
}
